import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/commands.md","filePath":"en/modules/dungeon/commands.md","lastUpdated":0}`),a={name:`en/modules/dungeon/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h1><p>The main command is <code>/edungeon</code>; the short alias is <code>/ed</code>. Player-side commands are open by default (<code>emakidungeon.play</code> defaults to <code>true</code>), while admin and editor commands require their own permissions</p><h2 id="player-commands" tabindex="-1">Player commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to “Player commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>/edungeon help</code></td><td>Show command help (same as running <code>/edungeon</code> with no arguments)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon list</code></td><td>List the currently available dungeons</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon enter &lt;dungeonId&gt;</code></td><td>Start a challenge and enter the dungeon; in a party <strong>only the leader may start</strong></td><td><code>emakidungeon.play</code> + <code>emakidungeon.dungeon.&lt;dungeonId&gt;</code></td></tr><tr><td><code>/edungeon leave</code></td><td>Leave the current dungeon; asks for a second confirmation first - type <code>confirm</code> in chat to leave, <code>cancel</code> to stay</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon cancel</code></td><td>Cancel an ongoing entry wait or challenge (any member can cancel during the ready window)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon ready</code></td><td>Confirm readiness during the ready window (the confirmation button works too)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon rewards</code></td><td>Open your personal reward box and claim payouts</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon stats [player] [dungeonId]</code></td><td>Show entry counts (day/week/month and cooldown) plus best results</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon rank &lt;dungeonId&gt;</code></td><td>Show the dungeon&#39;s top 10 leaderboard (score, duration, difficulty, party)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon globalchat &lt;on|off&gt;</code></td><td>Toggle global chat listening; <code>on</code> bridges chat in and out of the instance, <code>off</code> keeps dungeon chat inside the instance</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon editor &lt;dungeonId&gt;</code></td><td>Open the map editor and enter the dungeon&#39;s dedicated edit world</td><td><code>emakidungeon.editor</code></td></tr><tr><td><code>/edungeon recruit &lt;open|close|list|join&gt;</code></td><td>Party recruit board: <code>open &lt;dungeonId&gt; [difficulty]</code> publish a recruit (leader only), <code>close</code> close it, <code>list</code> list open recruits, <code>join &lt;number&gt;</code> join one</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon match &lt;join|leave&gt;</code></td><td>Local auto-match: <code>join &lt;dungeonId&gt; [difficulty]</code> enter the match queue, <code>leave</code> leave the queue</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon spectate &lt;next|prev&gt;</code></td><td>Switch the spectate target while spectating (next / previous); warns when you are not spectating</td><td><code>emakidungeon.play</code></td></tr></tbody></table><p>The recruit board and auto-match are controlled by the global <code>matchmaking</code> section (both report &quot;disabled&quot; when it is off), and recruits expire after <code>matchmaking.recruit-ttl-seconds</code>; after a match succeeds the leader starts the run with <code>/edungeon enter &lt;dungeonId&gt;</code></p><h2 id="party-subcommands" tabindex="-1">Party subcommands <a class="header-anchor" href="#party-subcommands" aria-label="Permalink to “Party subcommands”">​</a></h2><p><code>/edungeon party &lt;sub&gt;</code> manages your party:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th><th>Restrictions</th></tr></thead><tbody><tr><td><code>create</code></td><td>Create a new party (you become the leader)</td><td>Cannot create while already in a party</td></tr><tr><td><code>invite &lt;player&gt;</code></td><td>In a party: invite that player (leader only); not in a party: ask to join, handled by the invite mode</td><td>Leader-only when you already have a party</td></tr><tr><td><code>accept</code></td><td>The invitee accepts an invitation; the receiver of an application (the leader) approves it</td><td>Depends on whether you received an invite or an application</td></tr><tr><td><code>deny</code></td><td>Refuse a received invite (invitee) or reject an incoming application (leader)</td><td>Depends on whether you received an invite or an application</td></tr><tr><td><code>kick &lt;player&gt;</code></td><td>Remove a member</td><td>Leader only</td></tr><tr><td><code>leave</code></td><td>Leave the party (the leader hands over to another member first)</td><td>—</td></tr><tr><td><code>disband</code></td><td>Disband the whole party</td><td>Leader only</td></tr><tr><td><code>chat</code></td><td>Toggle the party channel: once on, your messages are visible to party members only</td><td>—</td></tr></tbody></table><p>The invite mode comes from the global <code>party.invite-mode</code> and decides what happens when a player without a party asks to join another: <code>public</code> joins directly, <code>apply</code> files an application waiting for the leader&#39;s approval, <code>invite</code> only lets invited players in (any other value behaves like <code>invite</code>). The party size cap is <code>party.max-size</code></p><h2 id="random-dungeon-commands" tabindex="-1">Random dungeon commands <a class="header-anchor" href="#random-dungeon-commands" aria-label="Permalink to “Random dungeon commands”">​</a></h2><p>Dungeons with <code>type: random</code> use the random-generation gameplay; operate them with <code>/edungeon random &lt;sub&gt;</code>:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>create &lt;dungeonId&gt; [players] [seed]</code></td><td>Create a random dungeon instance for the dungeon from the random-generation config; the player count affects the room count, and an empty seed is picked at random; <strong>available only for dungeons with <code>type: random</code></strong>, other types are refused outright</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>enter &lt;instanceId&gt;</code></td><td>Enter a created random dungeon instance</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>leave</code></td><td>Leave the current random dungeon instance</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>list</code></td><td>List running random dungeon instances (instance id, state, room count, seed)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>records</code></td><td>List instance records (record ids can be used with <code>replay</code>)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>stop &lt;instanceId&gt;</code></td><td>Force-stop a random dungeon instance</td><td><code>emakidungeon.admin</code></td></tr><tr><td><code>replay &lt;recordId&gt;</code></td><td>Re-derive the layout from an instance record for replay verification</td><td><code>emakidungeon.admin</code></td></tr><tr><td><code>reload</code></td><td>Reload <code>random-dungeon.yml</code> and the structure templates of all dungeons</td><td><code>emakidungeon.admin</code></td></tr></tbody></table><p>The structure templates (rooms / corridors) of a random dungeon come from the editor&#39;s region collection feature and are stored under <code>plugins/EmakiDungeon/world/&lt;dungeonId&gt;/structures/</code>; the collection flow is covered under the editor session commands below, and the generation parameters on the <a href="./configuration.html">Configuration</a> page</p><h2 id="editor-session-commands" tabindex="-1">Editor session commands <a class="header-anchor" href="#editor-session-commands" aria-label="Permalink to “Editor session commands”">​</a></h2><p>Run <code>/edungeon editor &lt;dungeonId&gt;</code> with the <code>emakidungeon.editor</code> permission to open an editing session:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>menu</code></td><td>Open the editing main panel; in a <code>type: random</code> dungeon it instead opens the region collection GUI</td></tr><tr><td><code>pos1</code> / <code>pos2</code></td><td>Record the first / second corner of a region (stand on each diagonal corner of the target area); in a <code>type: random</code> dungeon they frame the structure region to collect</td></tr><tr><td><code>anchor add &lt;id&gt; &lt;facing&gt; &lt;w&gt; &lt;h&gt;</code></td><td>Register a door point at the crosshair landing spot (within 12 blocks): the facing is <code>n</code> / <code>e</code> / <code>s</code> / <code>w</code>, and width and height are the door opening size (1–16); the region must be framed first, available only for <code>type: random</code> dungeons</td></tr><tr><td><code>anchor remove &lt;id&gt;</code></td><td>Remove a door point; available only for <code>type: random</code> dungeons</td></tr><tr><td><code>status</code></td><td>Show the current region collection session (structure type, tags, door point count, point count, floor); available only for <code>type: random</code> dungeons</td></tr><tr><td><code>mark &lt;type&gt; [id]</code></td><td>Place a marker on the block you are looking at (16 blocks reach); markers are staged in the session and written to <code>flow.yml</code> on save</td></tr><tr><td><code>marks</code></td><td>List the markers staged in this session</td></tr><tr><td><code>save</code></td><td>Write the staged markers and panel edits back to the template file and save the terrain (same as &quot;Save and write back&quot; in the panel)</td></tr><tr><td><code>fill &lt;block&gt;</code></td><td>Fill the area circled by <code>pos1</code> + <code>pos2</code> (written in frames, with a size cap)</td></tr><tr><td><code>test</code></td><td>Test start: runs the normal entry flow, <strong>counts nothing and never ranks</strong>; refused while unsaved changes exist</td></tr><tr><td><code>exit</code></td><td>Leave the session; refused while unsaved changes exist, so save or discard first</td></tr></tbody></table><p><code>anchor</code> and <code>status</code> report &quot;random type only&quot; in dungeons of other types; <code>menu</code> / <code>pos1</code> / <code>pos2</code> branch their semantics by dungeon type</p><p>Markers come in three coordinate flavors, 21 module types in total (one per <code>flow.yml</code> module):</p><table tabindex="0"><thead><tr><th>Type</th><th>How</th><th>Purpose</th></tr></thead><tbody><tr><td><code>entry</code></td><td>Point</td><td>Entry location (one per dungeon; duplicates are refused)</td></tr><tr><td><code>room</code></td><td>Region</td><td>Room</td></tr><tr><td><code>checkpoint</code></td><td>Region</td><td>Checkpoint</td></tr><tr><td><code>respawn</code></td><td>Point</td><td>Respawn point</td></tr><tr><td><code>exit</code></td><td>Point</td><td>Exit</td></tr><tr><td><code>gate</code></td><td>Region</td><td>Gate door area</td></tr><tr><td><code>spawn</code></td><td>Point</td><td>Spawn point</td></tr><tr><td><code>trigger</code></td><td>Region</td><td>Trigger zone</td></tr><tr><td><code>block</code></td><td>Point</td><td>Block interaction</td></tr><tr><td><code>chest</code></td><td>Point</td><td>Reward point</td></tr><tr><td><code>option</code></td><td>Point</td><td>Option node</td></tr><tr><td><code>tip</code></td><td>Point</td><td>Tip point</td></tr><tr><td><code>teleport</code></td><td>Region</td><td>Teleport zone</td></tr><tr><td><code>boundary</code></td><td>Region</td><td>Boundary zone</td></tr><tr><td><code>effect</code></td><td>Region</td><td>Effect zone</td></tr><tr><td><code>mechanism</code></td><td>Region</td><td>Mechanism</td></tr><tr><td><code>room_timer</code></td><td>Region</td><td>Room timer</td></tr><tr><td><code>kill_target</code></td><td>No coordinates</td><td>Kill target</td></tr><tr><td><code>item</code></td><td>Point</td><td>Item interaction</td></tr><tr><td><code>fx</code></td><td>Point</td><td>Effect point</td></tr><tr><td><code>temp_item</code></td><td>No coordinates</td><td>Temporary item</td></tr></tbody></table><p>How they work: point markers go on the block you are looking at; region markers need <code>pos1</code> + <code>pos2</code> corners (with no corner recorded yet, the first <code>mark</code> records the looked-at point as <code>pos1</code>); no-coordinate markers record config only. The configurable fields of each type are documented on <a href="./flow.html">Flow &amp; Triggers</a>. Boss is not a separate marker: mob entries in the waves of a spawn point are marked with <code>boss: true</code></p><p>The main editor panels (metadata, spawn points and waves, gates, branch options) are edited through GUIs. <strong>Markers and panel edits are only staged; nothing reaches the template files until you click &quot;Save and write back&quot; (or run <code>save</code>)</strong>, and exiting without saving discards everything.</p><p>In a <code>type: random</code> dungeon, right-clicking with an empty hand opens the <strong>region collection GUI</strong> (metadata and tags, door points, module points, selection, create-region panels and more): &quot;Create region&quot; on the main panel offers <strong>room / corridor</strong>, and the selection framed by the current <code>pos1</code> / <code>pos2</code> is written to <code>world/&lt;dungeonId&gt;/structures/</code> with the id auto-numbered as <code>room_N</code> / <code>corridor_N</code>; after the write the session automatically resets to a new region, so the next <code>pos1</code> / <code>pos2</code> frame collects the next structure</p><p>Only one editing session per dungeon template is allowed at a time</p><h2 id="admin-commands" tabindex="-1">Admin commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to “Admin commands”">​</a></h2><p><code>/edungeon admin &lt;sub&gt;</code> requires <code>emakidungeon.admin</code> (default OP):</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>instances</code></td><td>List running instances (id, dungeon, state, party, write-queue backlog)</td></tr><tr><td><code>inspect &lt;instanceId&gt;</code></td><td>Show instance details: difficulty, drop mode, type, test flag, party, elapsed time, and the flow timeline</td></tr><tr><td><code>stop &lt;instanceId&gt;</code></td><td>Force-stop a specific instance</td></tr><tr><td><code>status</code></td><td>Overview: instance count, live virtual threads, template count, per-pool usage, and write queues</td></tr><tr><td><code>reload</code></td><td>Reload the main configuration and <strong>all dungeon configs</strong>; running instances are untouched, only newly created instances pick up changes</td></tr><tr><td><code>validate</code></td><td>Validate every dungeon template and report missing <code>flow.yml</code> or invalid configurations</td></tr><tr><td><code>poolreset &lt;dungeonId&gt;</code></td><td>Force-reset the pool spare world of a dungeon</td></tr><tr><td><code>clearslots</code></td><td>Clear leftover pool slot reservations</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>admin</code> subcommands are dispatched before the player check, and <code>reload</code> has no player-only restriction: the console can run <code>/edungeon admin reload</code> directly, and so can bots and scripts. Players need <code>emakidungeon.admin</code>; the console holds every permission by default</p></div><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission nodes”">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>emakidungeon.play</code></td><td>All players</td><td>Entering, party, stats, and global listening player commands</td></tr><tr><td><code>emakidungeon.dungeon.*</code></td><td>All players</td><td>Entry to all dungeons (actually checked per <code>emakidungeon.dungeon.&lt;dungeonId&gt;</code>)</td></tr><tr><td><code>emakidungeon.bypass.limit</code></td><td>OP</td><td>Bypass entry counts and cooldowns</td></tr><tr><td><code>emakidungeon.bypass.escape</code></td><td>OP</td><td>Escape-protection exemption (debugging and maintenance)</td></tr><tr><td><code>emakidungeon.script</code></td><td>OP</td><td>Dungeon script loading and trigger registration</td></tr><tr><td><code>emakidungeon.editor</code></td><td>OP</td><td>Map editor sessions</td></tr><tr><td><code>emakidungeon.admin</code></td><td>OP</td><td>Instance management, force stop, reload, pool maintenance</td></tr><tr><td><code>emakidungeon.*</code></td><td>OP</td><td>Wildcard covering everything above</td></tr></tbody></table><p><code>emakidungeon.dungeon.&lt;dungeonId&gt;</code> is <strong>dynamically registered</strong> on startup and reload for every dungeon folder under <code>world/</code>, and defaults to open for all players; deleting the dungeon removes the node. For a members-only dungeon, turn the default off in your permission plugin and grant the node to the right groups</p><h2 id="command-rules-inside-a-dungeon" tabindex="-1">Command rules inside a dungeon <a class="header-anchor" href="#command-rules-inside-a-dungeon" aria-label="Permalink to “Command rules inside a dungeon”">​</a></h2><p>Commands run by players inside an instance pass two gates:</p><ol><li><strong>Escape blacklist</strong> (<code>escape.blacklist</code>, supports <code>*</code> wildcards): a hit is refused immediately with &quot;command restricted in this dungeon (escape blacklist)&quot;, and <strong>no allow-rule can override this layer</strong></li><li><strong>Command guard</strong> (<code>commands.mode</code>, blacklist or whitelist): evaluated against the global <code>commands.rules</code> and the dungeon-level <code>commands.allow</code>, refusing with &quot;command restricted in this dungeon (command guard)&quot;</li></ol><p>Configuration details are on the <a href="./configuration.html">Configuration</a> page</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};